INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Leitbild immer technische Details enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Vision und Werte"}, {"text": "Ja", "correct": false, "because": "Technik nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Leitbild für ein IT-Unternehmen erstelle?', 3, '[{"text": "Unternehmenswerte", "correct": true, "because": "Leitet Kultur"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Designaspekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören typischerweise zu einem IT-Leitbild?', 5, '[{"text": "Vision", "correct": true, "because": "Gibt Richtung vor"}, {"text": "Werte", "correct": true, "because": "Definiert Kultur"}, {"text": "Technische Spezifikationen", "correct": false, "because": "Nicht enthalten"}, {"text": "Marketingtexte", "correct": false, "because": "Kein Kernbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Leitbild motiviert Mitarbeiter. b) Es ist immer rechtlich bindend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht rechtlich bindend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Leitbild für ein IT-Unternehmen entwerfe?', 4, '[{"text": "Unternehmensziele", "correct": false, "because": "Kern des Leitbilds"}, {"text": "Mitarbeiterinput", "correct": false, "because": "Fördert Akzeptanz"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Leitbildfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Leitbild nur für Kunden relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Mitarbeiter wichtig"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Leitbild in der IT?', 3, '[{"text": "Identität schaffen", "correct": true, "because": "Definiert Unternehmen"}, {"text": "Schnelle Projekte", "correct": false, "because": "Kein direktes Ziel"}, {"text": "Weniger Werte", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sind für ein IT-Leitbild entscheidend?', 5, '[{"text": "Mission", "correct": true, "because": "Beschreibt Zweck"}, {"text": "Werteorientierung", "correct": true, "because": "Leitet Verhalten"}, {"text": "Technische Details", "correct": false, "because": "Nicht enthalten"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Leitbild stärkt die Unternehmenskultur. b) Es enthält immer Produktbeschreibungen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Produkte nicht zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein IT-Leitbild?', 4, '[{"text": "Vision", "correct": false, "because": "Gibt Richtung"}, {"text": "Unternehmensethik", "correct": false, "because": "Definiert Werte"}, {"text": "Hardwareliste", "correct": true, "because": "Kein Leitbildfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Leitbild immer unveränderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Kann angepasst werden"}, {"text": "Ja", "correct": false, "because": "Flexibel bei Veränderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Leitbild für ein IT-Unternehmen?', 4, '[{"text": "Mitarbeitermotivation", "correct": true, "because": "Fördert Zusammenhalt"}, {"text": "Kundenvertrauen", "correct": true, "because": "Zeigt Werte"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Leitbild nur für große Firmen wichtig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMU profitieren"}, {"text": "Ja", "correct": false, "because": "Für alle relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Leitbild für ein IT-Unternehmen zu erstellen?', 3, '[{"text": "Teamworkshops", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Technische Specs", "correct": false, "because": "Nicht enthalten"}, {"text": "Bunte Layouts", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Leitbild gibt Orientierung. b) Es ist immer kurzfristig ausgerichtet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Langfristige Vision"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem IT-Leitbild?', 5, '[{"text": "Unternehmensziele", "correct": true, "because": "Gibt Richtung"}, {"text": "Mitarbeiterwerte", "correct": true, "because": "Definiert Kultur"}, {"text": "Hardwareauswahl", "correct": false, "because": "Kein Leitbildfaktor"}, {"text": "Büroausstattung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Leitbild für ein IT-Unternehmen erstelle?', 3, '[{"text": "Mission", "correct": false, "because": "Kernbestandteil"}, {"text": "Werte", "correct": false, "because": "Leitet Verhalten"}, {"text": "Farbschema", "correct": true, "because": "Ästhetisch, nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dient ein Leitbild nur der Außendarstellung?', 3, '[{"text": "Nein", "correct": true, "because": "Auch interne Orientierung"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Leitbild die IT-Strategie ersetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein IT-Leitbild?', 4, '[{"text": "Langfristige Vision", "correct": true, "because": "Gibt Richtung vor"}, {"text": "Technische Details", "correct": false, "because": "Nicht enthalten"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Kein Fokus"}]');
